SELECT SUM(passenger_flow) AS bus_total
FROM bus_flow_hour
WHERE stat_date = '2026-08-24';

SELECT COUNT(DISTINCT geohash) AS qualifying_grids
FROM grid_flow_hour
WHERE stat_date = '2026-08-24' AND ridehail_orders >= 100;

SELECT SUM(bike_locks) AS lock_total
FROM grid_flow_hour
WHERE stat_date = '2026-08-24';
